# Review package: aef2cc62c9a56907d1bfbf6e439396f4e93d50cd..9b9f2e6196837e7ceb33edf54d223a6825ff336e

## Commits
9b9f2e6 test: use real curly quotes in sentenceCount dialogue test

## Files changed
 test/sentenceCount.test.js | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)

## Diff
diff --git a/test/sentenceCount.test.js b/test/sentenceCount.test.js
index bc91b6d..23a5eee 100644
--- a/test/sentenceCount.test.js
+++ b/test/sentenceCount.test.js
@@ -61,12 +61,12 @@ test('counts the eight sentences of the reference passage', () => {
   assert.equal(sentenceCount(PASSAGE), 8);
 });

 test('matches every row of the reference table', () => {
   for (const [text, expected] of CASES) {
     assert.equal(sentenceCount(text), expected, JSON.stringify(text));
   }
 });

 test('handles curly-quoted dialogue correctly', () => {
-  assert.equal(sentenceCount('He said "Go." Then left.'), 2);
+  assert.equal(sentenceCount('“Go.” Then left.'), 2);
 });

